<template>
  <view class="help-page">
    <view class="fixed-page-header page-header"><view class="header-back" @tap="goBack" aria-label="返回"><uv-icon name="arrow-left" color="#2B3748" size="22"></uv-icon></view><view class="header-copy"><text class="header-title">帮助与反馈</text><text class="header-subtitle">有问题，我们随时在这里</text></view><view class="service-button" @tap="callService"><uv-icon name="kefu-ermai" color="#3389F7" size="17"></uv-icon><text>客服</text></view></view>
    <scroll-view class="help-scroll" scroll-y :show-scrollbar="false"><view class="help-content">
      <view class="help-hero"><view><text>遇到问题？</text><text>先看看这些常见解答</text></view><view class="hero-icon"><uv-icon name="question-circle-fill" color="#FFFFFF" size="40"></uv-icon></view></view>
      <view class="search-box"><uv-icon name="search" color="#95A1B0" size="19"></uv-icon><input v-model="keyword" placeholder="搜索换电、暂存、报修问题" placeholder-class="search-placeholder" confirm-type="search" /></view>
      <view class="category-row"><view v-for="item in categories" :key="item.key" class="category-item" :class="{ active: activeCategory === item.key }" @tap="activeCategory = item.key"><uv-icon :name="item.icon" :color="activeCategory === item.key ? '#3389F7' : item.color" size="18"></uv-icon><text>{{ item.label }}</text></view></view>
      <view class="section-title"><text>常见问题</text><text>{{ filteredFaqs.length }} 条</text></view>
      <view class="faq-card"><view v-for="(item,index) in filteredFaqs" :key="item.id" class="faq-row" @tap="toggleFaq(item)"><view class="faq-question"><text>{{ item.question }}</text><uv-icon :name="item.open ? 'arrow-up' : 'arrow-down'" color="#8F9BAB" size="15"></uv-icon></view><view v-if="item.open" class="faq-answer">{{ item.answer }}</view><view v-if="index < filteredFaqs.length - 1" class="faq-divider"></view></view><view v-if="!filteredFaqs.length" class="faq-empty">没有找到相关问题，欢迎直接提交反馈</view></view>
      <view class="section-title feedback-title"><text>意见反馈</text><text>我们会持续优化</text></view>
      <view class="feedback-card"><text class="field-label">你遇到了什么问题？</text><textarea v-model.trim="feedback" maxlength="300" placeholder="请尽量描述发生时间、站点、故障现象等信息" placeholder-class="textarea-placeholder" auto-height /><view class="textarea-count">{{ feedback.length }}/300</view><view class="feedback-contact"><uv-icon name="phone-fill" color="#5C9CED" size="16"></uv-icon><input v-model.trim="phone" type="number" maxlength="11" placeholder="留下手机号，方便我们联系你（选填）" placeholder-class="contact-placeholder" /></view><view class="submit-button" :class="{ disabled: !feedback }" @tap="submitFeedback">提交反馈</view></view>
      <view class="emergency-card"><view class="emergency-icon"><uv-icon name="warning-fill" color="#ED9059" size="20"></uv-icon></view><view><text>紧急安全问题请优先联系客服</text><text>电池出现发热、异味、进水等情况时，请立即停止使用。</text></view><uv-icon name="arrow-right" color="#ABB6C4" size="14"></uv-icon></view>
      <view class="bottom-spacer"></view>
    </view></scroll-view>
  </view>
</template>

<script>
const FAQS = [
  { id: 'swap', category: 'swap', question: '扫码后没有打开换电柜怎么办？', answer: '请确认网络正常并将二维码完整置于扫描框内。如仍未开柜，请在站点详情页重新预约，或联系客服协助处理。' },
  { id: 'battery', category: 'swap', question: '换到的电池电量不足怎么办？', answer: '请先在“我的电池”查看实时状态。如电量明显异常，可立即在“故障上报”提交工单，平台会优先处理。' },
  { id: 'storage', category: 'storage', question: '暂存电池到期后如何取回？', answer: '进入“我的订单”找到暂存订单，点击“立即取回”，再按柜机指引操作即可。到期后可能会产生额外暂存费用。' },
  { id: 'repair', category: 'repair', question: '提交报修后多久会有回复？', answer: '一般工单会在 2 小时内受理。紧急安全问题请直接拨打客服热线，不要继续使用异常电池。' },
  { id: 'fee', category: 'account', question: '换电费用和优惠券如何计算？', answer: '结算时系统会优先匹配可用的优惠券和会员权益，最终金额以订单结算页展示为准。' },
  { id: 'deposit', category: 'account', question: '押金如何申请退还？', answer: '满足无在用电池、无未完成订单等条件后，可通过客服中心申请退还。审核完成后将原路退回。' }
]
export default { data() { return { keyword: '', activeCategory: 'all', phone: '', feedback: '', faqs: FAQS.map(item => ({ ...item, open: false })) } }, computed: { categories() { return [{ key: 'all', label: '全部', icon: 'grid-fill', color: '#718095' }, { key: 'swap', label: '换电', icon: 'reload', color: '#3389F7' }, { key: 'storage', label: '暂存', icon: 'folder', color: '#7568EC' }, { key: 'repair', label: '报修', icon: 'edit-pen', color: '#EA9851' }, { key: 'account', label: '账户', icon: 'account-fill', color: '#39AE8A' }] }, filteredFaqs() { const keyword = this.keyword.trim().toLowerCase(); return this.faqs.filter(item => (this.activeCategory === 'all' || item.category === this.activeCategory) && (!keyword || `${item.question}${item.answer}`.toLowerCase().includes(keyword))) } }, methods: { goBack() { uni.navigateBack({ delta: 1, fail: () => uni.reLaunch({ url: '/pages/index/index?tab=4' }) }) }, callService() { uni.makePhoneCall({ phoneNumber: '4008888899', fail: () => uni.showToast({ title: '请拨打 400-888-8899', icon: 'none' }) }) }, toggleFaq(item) { item.open = !item.open }, submitFeedback() { if (!this.feedback) return uni.showToast({ title: '请先填写反馈内容', icon: 'none' }); if (this.phone && !/^1\d{10}$/.test(this.phone)) return uni.showToast({ title: '请输入正确的联系电话', icon: 'none' }); uni.showModal({ title: '反馈已提交', content: '我们已收到你的反馈，会尽快核查处理。处理进度将通过消息中心同步。', showCancel: false, success: () => { this.feedback = ''; this.phone = '' } }) } } }
</script>

